M = [x for x in M if x]
if os.environ.get('MUTANTS'): M = [x for x in M if x[0] in os.environ['MUTANTS'].split(',')]   # run a subset
caught = 0; equiv = 0; missing = 0; notcaught = []
for name, a, b, eq in M:
    if src.count(a) < 1: print(f'mutant {name:28s} PATTERN MISSING'); missing += 1; continue
    open(f'{out}/m.rs', 'w').write(src.replace(a, b, 1))
    res = []
    for only in ('16 1 0', '5 0 1'):
        r = subprocess.run(['bash', f'{here}/cpu_cmp.sh'], env={**os.environ, 'CPU_RS': f'{out}/m.rs', 'N': '12000', 'ONLY': only}, capture_output=True, text=True)
        res.append(r.returncode)
        if 'COMPILE-FAIL' in r.stdout: print(f'mutant {name:28s} COMPILE-FAIL'); print(r.stdout[-400:]); break
        if r.returncode: break
    else:
        pass
    if 'COMPILE-FAIL' in r.stdout: missing += 1; continue
    if eq:
        equiv += 1; print(f'mutant {name:28s} ' + ('equivalent (expected not caught)' if not any(res) else '*** EQUIVALENT MUTANT WAS CAUGHT')); continue
    if any(res): caught += 1; print(f'mutant {name:28s} CAUGHT')
    else: notcaught.append(name); print(f'mutant {name:28s} *** NOT CAUGHT')
tot = len(M) - equiv - missing
print(f'sabotage: {caught} of {tot} non-equivalent mutants caught, {equiv} equivalent, {missing} pattern missing / compile-fail, not caught: {notcaught}')
sys.exit(0 if caught == tot and not missing else 1)
